function slugify(value: string) {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

function legacyToRows() {
  return (Object.entries(LEGACY_REPORT_DATA) as Array<[Country, Record<LegacyPostType, LegacyReportRow[]>]>).flatMap(
    ([country, groups]) =>
      (Object.entries(groups) as Array<[LegacyPostType, LegacyReportRow[]]>).flatMap(([type, rows]) =>
        rows.map((row) => {
          const contentType: ContentType = type === "reels" ? "reel" : "post";
          return {
            id: `legacy-${country.toLowerCase()}-${contentType}-${row.month_key}-${slugify(row.title)}-${slugify(row.date)}`,
            country,
            platform: "instagram" as const,
            contentType,
            sourceName: row.title,
            title: row.title,
            date: row.date,
            month_key: row.month_key,
            spendEur: row.spend,
            reach: row.reach,
            cpmEur: row.cpm || null,
            resultType: "post_engagement" as const,
            results: row.engagements,
            costPerResultEur: row.cpe,
            engagements: row.engagements,
            cpeEur: row.cpe,
            landingPageViews: null,
            costPerLandingPageViewEur: null,
            rankingEligible: true,
            thumbnail: row.thumb,
            snippet: row.snippet,
          } satisfies ReportRow;
        }),
      ),
  );
}

export const REPORT_DATA = [
  ...legacyToRows(),
  ...JUNE_2026_RECORDS,
  ...JULY_2026_RECORDS,
  ...AUGUST_2026_RECORDS,
] satisfies ReportRow[];
